from collections import Counter
import heapq


def _dependency_solver(data, order, maximize):
    packages = data["packages"]
    names = sorted(packages, reverse=(order == "descending"))
    roots = data["roots"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows_by_version = {}
    options = []

    for name in names:
        rows = {row["version"]: row for row in packages[name]}
        rows_by_version[name] = rows
        allowed = [version for version in rows
                   if version not in blocked.get(name, [])
                   and (name not in pins or version == pins[name])]
        if name not in roots:
            allowed.append(None)
        else:
            low, high = roots[name]
            allowed = [v for v in allowed if v is not None and low <= v <= high]
        options.append(allowed)

    def active_deps(row):
        return [d for d in row.get("deps", [])
                if not d.get("feature") or d["feature"] in features]

    for values in product(*options):
        chosen = dict(zip(names, values))
        installed = {name for name, version in chosen.items()
                     if version is not None}
        if any(name not in installed for name in roots):
            continue

        graph = {name: [] for name in installed}
        valid = True
        for name in installed:
            row = rows_by_version[name][chosen[name]]
            for dep in active_deps(row):
                target = dep["name"]
                version = chosen[target]
                if version is None or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                graph[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph[name])
        if reachable != installed:
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in installed):
            continue
        vector = tuple(-1 if v is None else v for v in values)
        if 'best' not in locals() or (vector > best if maximize else vector < best):
            best = vector
            best_values = chosen

    if 'best' not in locals():
        return {"error": "unsatisfiable"}
    return {"versions": {name: version for name, version in best_values.items()
                          if version is not None}}


def _build_component_01():
    return lambda data: _dependency_solver(data, "ascending", True)


def _build_component_02():
    return lambda data: _dependency_solver(data, "ascending", False)


